const parseDay=d=>new Date(d+'T12:00:00Z');
const dayAdd=(d,n)=>{const x=parseDay(d);x.setUTCDate(x.getUTCDate()+n);return x.toISOString().slice(0,10)};
const weekday=d=>parseDay(d).getUTCDay();
const monthAdd=(m,n)=>{let [y,x]=m.split('-').map(Number);return new Date(Date.UTC(y,x-1+n,1,12)).toISOString().slice(0,7)};
const monday=d=>dayAdd(d,-((weekday(d)+6)%7));
