function tint(hex,a){const h=hex.replace('#','');const c=[0,2,4].map(i=>parseInt(h.slice(i,i+2),16));return '#'+c.map(x=>Math.round(255-(255-x)*a).toString(16).padStart(2,'0')).join('')}

