const moodOf=c=>{const base=(c?.mood&&MOOD_BY_ID[c.mood.id])||null;if(!base)return null;const e=c.mood.energy,h=c.mood.happiness;if(Number.isInteger(e)&&e>=1&&e<=5&&Number.isInteger(h)&&h>=1&&h<=5)return {...base,e,v:h,r:5-e,c:h-1};return base};
