function quadOfMood(m){return m.r===2&&m.c===2?'neutral':m.r<2?(m.c<3?'red':'yellow'):(m.c<3?'blue':'green')}
function quadOfScore(e,v){if(Math.abs(e-3)<.5&&Math.abs(v-3)<.5)return 'neutral';const top=e>=3.5,left=v<3.5;return top?(left?'red':'yellow'):(left?'blue':'green')}
