const strength=(q,dist,boost=0)=>q==='neutral'?.32+boost:Math.min(.68,(q==='yellow'?.32:.2)+dist*.12+boost);
// Quiet lavender → ocean blue → warm ivory → sunshine → coral.
const KONA_ENERGY_COLORS=['#D8CAF0','#B9D7EE','#F4F1E9','#F8E399','#F3AB9B'];
const KONA_ENERGY_LABELS=[KonaI18n.t("Depleted"),KonaI18n.t("Low"),KonaI18n.t("Steady"),KonaI18n.t("Energized"),KonaI18n.t("Full of energy")];
const KONA_MOOD_LABELS=[KonaI18n.t("Rough"),KonaI18n.t("Low"),KonaI18n.t("Neutral"),KonaI18n.t("Good"),KonaI18n.t("Great")];
// Rows: energy 1..5. Columns: mood 1..5. Stored legacy IDs stay intact.
const KONA_FEELINGS=[
 [KonaI18n.t("Depleted"),KonaI18n.t("Exhausted"),KonaI18n.t("Still"),KonaI18n.t("Relaxed"),KonaI18n.t("Serene")],
 [KonaI18n.t("Drained"),KonaI18n.t("Weary"),KonaI18n.t("Quiet"),KonaI18n.t("Calm"),KonaI18n.t("Peaceful")],
 [KonaI18n.t("Down"),KonaI18n.t("Uneasy"),KonaI18n.t("Neutral"),KonaI18n.t("Content"),KonaI18n.t("Happy")],
 [KonaI18n.t("Frustrated"),KonaI18n.t("Worried"),KonaI18n.t("Unsettled"),KonaI18n.t("Upbeat"),KonaI18n.t("Joyful")],
 [KonaI18n.t("Overwhelmed"),KonaI18n.t("Tense"),KonaI18n.t("Restless"),KonaI18n.t("Enthusiastic"),KonaI18n.t("Excited")]
];
function konaFeeling(m){if(!m)return '';const e=Number(m.e??m.energy),h=Number(m.v??m.happiness);return Number.isInteger(e)&&e>=1&&e<=5&&Number.isInteger(h)&&h>=1&&h<=5?KONA_FEELINGS[e-1][h-1]:''}
function konaEnergyLabel(e){return KONA_ENERGY_LABELS[e-1]||''}
function konaFeelingIcon(dimension,level){
 if(dimension==='energy')return KonaI18n.markup("<svg viewBox=\"0 0 48 12\" aria-hidden=\"true\" focusable=\"false\">")+Array.from({length:5},(_,j)=>'<circle cx="'+(4+j*10)+'" cy="6" r="3" fill="currentColor" opacity="'+(j<level?'1':'.15')+'"/>').join('')+'</svg>';
 const mouths=['M10 21 Q18 12 26 21','M11 20 Q18 15 25 20','M11 19 H25','M10 17 Q18 25 26 17','M10 17 Q18 29 26 17 Z'];
 return KonaI18n.markup("<svg viewBox=\"0 0 36 32\" aria-hidden=\"true\" focusable=\"false\"><circle cx=\"18\" cy=\"16\" r=\"13\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"/><circle cx=\"13\" cy=\"12\" r=\"1.4\" fill=\"currentColor\"/><circle cx=\"23\" cy=\"12\" r=\"1.4\" fill=\"currentColor\"/><path d=\"")+mouths[level-1]+'" fill="'+(level===5?'currentColor':'none')+'" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>';
}
function konaFeelingSummary(energy,happiness){
 const feeling=konaFeeling({e:energy,v:happiness});
 return feeling||'';
}
function konaMoodShade(energy,happiness){
 // Energy determines the hue. Mood changes ONLY its lightness/tint.
 // 1 = muted/darker, 3 = energy base, 5 = lighter/brighter.
 const e=Math.max(1,Math.min(5,Math.round(Number(energy)||3)));
 const h=Math.max(1,Math.min(5,Math.round(Number(happiness)||3)));
 const base=KONA_ENERGY_COLORS[e-1], mixTarget=h<=2?'#68616A':'#FFFFFF';
 const fraction=[.22,.10,0,.18,.34][h-1];
 return '#'+[1,3,5].map(i=>{
  const v=parseInt(base.slice(i,i+2),16),t=parseInt(mixTarget.slice(i,i+2),16);
  return Math.round(v*(1-fraction)+t*fraction).toString(16).padStart(2,'0');
 }).join('').toUpperCase();
}

// On_HARU Daily Review and Archive: 25 semantic color pairs.
// Rows = Energy 1–5, columns = Mood 1–5. Display-only; no saved-data changes.
