const KONA_REVIEW_MOOD_LIGHT=[
 ['#D1D5EA','#CFDCE8','#CDDEE0','#C7E3DA','#BCE2D7'],
 ['#D9CCE5','#D7D8E4','#D0DED8','#C7E2D5','#B9E2CE'],
 ['#E5D1DD','#E1D4DB','#DAD7CE','#DDE2C5','#D6E3B6'],
 ['#EDC5CD','#EECFCE','#EFD8C6','#EFDFB5','#F0D097'],
 ['#E7AAB8','#EAB7B5','#EDC6B5','#EDC49B','#E9B47A']
];
const KONA_REVIEW_MOOD_DARK=[
 ['#675477','#5D617A','#4D6977','#3E7376','#397568'],
 ['#75577F','#6A6080','#53727A','#3C796F','#417A60'],
 ['#805978','#74657D','#617372','#537C69','#5D7C55'],
 ['#8A576D','#815E70','#7D6A68','#7E7159','#877348'],
 ['#8E5363','#945D62','#8E685C','#906B4F','#95683D']
];
function konaReviewMoodTone(node,energy,mood){
 const h=Number(mood),e=energy===null||energy===undefined||energy===''?3:Number(energy);
 if(!Number.isInteger(h)||h<1||h>5||!Number.isInteger(e)||e<1||e>5)return false;
 node.classList.add('onharu-mood-tone');
 node.style.setProperty('--onharu-mood-light',KONA_REVIEW_MOOD_LIGHT[e-1][h-1]);
 node.style.setProperty('--onharu-mood-dark',KONA_REVIEW_MOOD_DARK[e-1][h-1]);
 node.dataset.moodEnergy=String(e);node.dataset.moodRating=String(h);
 return true;
}
const moodColor=(m,boost=0)=>konaMoodShade(m?.e,m?.v);
const scoreColor=(sc,boost=0)=>konaMoodShade(sc?.e,sc?.v);
const moodChip=m=>KonaI18n.format("<span class=\"mchip\" style=\"background:⟪0⟫\">⟪1⟫</span>",[moodColor(m),escapeHTML(konaFeeling(m)||moodEnglishNames[m.id]||m.n)],false);
function dayScore(d){const v=db.days[d];if(!v)return null;const ms=PHASES.map(p=>moodOf(v.checkins?.[p])).filter(Boolean);if(!ms.length)return null;return{e:ms.reduce((s,m)=>s+m.e,0)/ms.length,v:ms.reduce((s,m)=>s+m.v,0)/ms.length,n:ms.length}}
const lastMood=d=>{for(const p of ['evening','noon','morning']){const m=moodOf(readCheck(d,p));if(m)return m}return null};
const hasDevotion=d=>(db.days[d]?.sessions||[]).some(s=>s.kind==='devotion'||s.kind==='prayer');
function dayHasData(d){const v=db.days[d];return !!(v&&(v.headline||v.emoji||Object.values(v.meals||{}).some(x=>String(x||'').trim())||Object.values(v.eventNoteTitles||{}).some(Boolean)||Object.values(v.timeNotes||{}).some(slot=>Object.values(slot).some(n=>n?.text?.trim()))||PHASES.some(p=>hasCheck(v.checkins?.[p]))||classReviewHasContent(v.checkins?.noon)||(v.sessions||[]).length))}
const answeredOn=d=>db.prayers.filter(p=>p.answered===d);
const dayEvents=d=>db.events.filter(e=>e.since<=d&&(!e.until||e.until>=d)&&!db.skip[e.id+'|'+d]&&(e.repeat==='daily'||e.repeat==='weekly'&&(e.days||[]).includes(weekday(d))||e.repeat==='none'&&e.since===d))
  .map(e=>{const o=db.overrides[e.id+'|'+d];return o?{...e,...o,overridden:true}:e})
  .sort((a,b)=>a.start.localeCompare(b.start)||a.end.localeCompare(b.end));
const itemsDue=d=>db.tasks.filter(t=>t.since<=d&&(!t.until||t.until>=d)&&(t.repeat==='daily'||t.repeat==='weekly'&&(t.days||[]).includes(weekday(d))||t.repeat==='none'&&(!db.checks[t.id+'|single']||db.checks[t.id+'|single'].date>=d))).sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999'));
const taskKey=(t,d)=>t.id+'|'+(t.repeat==='none'?'single':d);
const isTaskDone=(t,d)=>!!db.checks[taskKey(t,d)];
const completedOn=d=>itemsDue(d).filter(t=>t.repeat==='none'?db.checks[t.id+'|single']?.date===d:isTaskDone(t,d)).length;
function firstSentence(s){const line=(s||'').split(/\n/).map(x=>x.trim()).find(Boolean)||'';const m=line.match(/^(.+?[.!?。])(\s|$)/);return (m?m[1]:line).replace(/\s+/g,' ').slice(0,72)}
function headlineSuggest(d){const v=db.days[d];if(!v||v.headline)return '';return firstSentence(v.checkins?.evening?.note)}
// L3: 체크인마다 직전(3시간 이내) 일정을 찾아 그 일정 뒤 기분으로 연결
function afterMoods(d){
  const v=db.days[d],out={};if(!v)return out;
  const es=dayEvents(d).filter(e=>INFLUENCE_CATS.includes(e.category));
  for(const p of PHASES){const c=v.checkins?.[p],m=moodOf(c);if(!m)continue;const t=checkTime(c,p);if(t===null)continue;let best=null;
    for(const e of es){const z=mins(e.end);if(z<=t&&t-z<=180&&(!best||z>mins(best.end)))best=e}
    if(best)out[best.id]=m}
  return out;
}

