const activePrayers=()=>db.prayers.filter(p=>!p.answered);
const prayerOrder=()=>activePrayers().slice().sort((a,b)=>(a.lastPrayed||'').localeCompare(b.lastPrayed||'')||(a.since||'').localeCompare(b.since||''));
function randomPrayer(except=''){
  const active=activePrayers(),choices=active.length>1?active.filter(p=>p.id!==except):active;
  if(!choices.length)return null;
  const values=new Uint32Array(1);if(window.crypto?.getRandomValues)window.crypto.getRandomValues(values);else values[0]=Math.floor(Math.random()*0x100000000);
  return choices[values[0]%choices.length];
}
function todayPrayer(){const t=nowLocal(),act=activePrayers();if(!act.length)return null;const v=day(t);let p=act.find(x=>x.id===v.prayerPick);if(!p){p=randomPrayer();v.prayerPick=p.id;save()}return p}
function nextPrayer(){const cur=todayPrayer();if(!cur||activePrayers().length<2)return;const next=randomPrayer(cur.id);day(nowLocal()).prayerPick=next.id;save();render()}
function markPrayed(p,d){if((p.lastPrayed||'')<d){p.prevPrayed=p.lastPrayed||null;p.lastPrayed=d;p.count=(p.count||0)+1}}
function unmarkPrayed(p,d){if(p.lastPrayed===d){p.lastPrayed=p.prevPrayed||null;p.prevPrayed=null;p.count=Math.max(0,(p.count||0)-1)}}
function togglePrayed(p){const t=nowLocal(),had=p.lastPrayed===t;if(guardedMutation(()=>{if(had)unmarkPrayed(p,t);else markPrayed(p,t)},KonaI18n.t("Prayer log not saved."))){render();toast(had?KonaI18n.t("Prayer log removed"):KonaI18n.t("Prayer logged"))}}

