function normalizeDailyHeadline(value){return String(value||'').replace(/[\r\n]+/g,' ').replace(/\s+/g,' ').trim().slice(0,144)}
function renderCapture(){renderToday();}
function renderToday(){
  const v=day(date),sug=headlineSuggest(date),h=$('dayHeadline');
  $('dayEmoji').textContent=v.emoji||'🌺';
  const editing=document.activeElement===h,headline=editing?String(v.headline||''):normalizeDailyHeadline(v.headline);if(!editing&&headline!==v.headline){v.headline=headline;save()}
  if(!editing)h.value=headline;
  h.placeholder=normalizeDailyHeadline(sug)||KonaI18n.t("One-line note for today",true);h.classList.toggle('suggest',!!sug);
  $('useSuggest').classList.toggle('hidden',!sug||!!h.value);
  $('todayTasksHeading').textContent=date===nowLocal()?KonaI18n.t("Today's tasks"):KonaI18n.t("Selected day's tasks");
  $('todayScheduleHeading').textContent=date===nowLocal()?KonaI18n.t("Today's schedule"):KonaI18n.t("Selected day's schedule");
  renderHero();renderActiveSessionBanner();renderPins();renderWeekLecture();$('todayTaskCard').hidden=!taskExpanded;
  const tl=$('todayTaskList');tl.replaceChildren();const tasks=itemsDue(date),pins=new Set(v.pins||[]);
  tasks.filter(t=>!isTaskDone(t,date)).sort((a,b)=>Number(pins.has(taskKey(b,date)))-Number(pins.has(taskKey(a,date)))).forEach(t=>tl.append(taskRow(t,date,{focusButton:true})));
  const completed=tasks.filter(t=>isTaskDone(t,date));if(completed.length){const details=el('details','done-tasks');details.open=!!db.settings.showDoneTasks;details.append(el('summary','micro',KonaI18n.format("Done (⟪0⟫)",[completed.length],false)));completed.forEach(t=>details.append(taskRow(t,date,{focusButton:true})));details.ontoggle=()=>{db.settings.showDoneTasks=details.open;save()};tl.append(details)}
  if(!tasks.length)tl.append(el('div','dash','–'));
  renderHomeCheckins();renderTimeline();renderHomeNight();scheduleAutoScroll();
}
function renderHomeCheckins(){
 const root=$('todayCheckins');root.replaceChildren();
 const labels={morning:KonaI18n.t("Morning"),noon:KonaI18n.t("Midday"),evening:KonaI18n.t("Evening"),night:KonaI18n.t("Day wrap-up")};
 const now=date===nowLocal()?mins(timeLocal()):-1;
 for(const p of PHASES){
  const c=readCheck(date,p),m=moodOf(c),actual=c?.moodTime?hm(mins(c.moodTime)):'',done=hasCheck(c),current=now>=0&&p===(now<720?'morning':now<1020?'noon':now<1260?'evening':'night');
  const status=[actual,m?m.n:'',done&&!m?'✓':''].filter(Boolean).join(' · ');
  const b=el('button','home-checkin'+(done?' is-done':'')+(current?' is-current':''),KonaI18n.format("<span class=\"journey-dot\" aria-hidden=\"true\">⟪0⟫</span><b>⟪1⟫</b><small>⟪2⟫</small>",[done?'✓':'',labels[p],escapeHTML(status||KonaI18n.t("Not yet"))],false));
  b.type='button';if(current)b.setAttribute('aria-current','step');b.setAttribute('aria-label',KonaI18n.format("⟪0⟫ check-in⟪1⟫",[labels[p],actual?KonaI18n.t(", recorded at ",true)+actual:done?KonaI18n.t(", recorded, no time entered",true):KonaI18n.t(", no entry yet",true)],true));b.onclick=()=>nav('checkin',{phase:p});root.append(b);
 }
}
