function mealPhase(e,events=dayEvents(date)){
 if(e.id==='__morning_checkin')return 'morning';if(e.id==='__day_wrap')return 'night';
 const meals=events.filter(x=>x.category==='meal'&&!/휴식|간식|break|snack/i.test(x.title));
 const phaseOf=x=>/아침|breakfast/i.test(x.title)?'morning':/점심|lunch/i.test(x.title)?'noon':/저녁|dinner/i.test(x.title)?'evening':mins(x.start)<720?'morning':mins(x.start)<1020?'noon':'evening';
 const p=phaseOf(e);return meals.find(x=>phaseOf(x)===p)?.id===e.id?p:null;
}
