function eventMemoText(d,id){
 const v=db.days[d]||{},parts=[];const ids=[id,...(!(v.unifiedNotesSaved||[]).includes(id)?db.settings?.morningLectureAliases?.[id]||[]:[])];
 for(const key of ids){if(v.eventNotes?.[key])parts.push(v.eventNotes[key]);if(!(v.legacyMergedIds||[]).includes(key))for(const slot of Object.values(v.timeNotes||{})){const n=slot[key],text=typeof n==='string'?n:n?.text;if(text?.trim())parts.push(text)}}
 return [...new Set(parts.filter(Boolean))].join('\n\n');
}

