 let moved=false;rail.onpointerdown=()=>{moved=false};rail.oninput=()=>{moved=true;selected.textContent=text(+rail.value);rail.setAttribute('aria-valuetext',text(+rail.value))};rail.onchange=()=>{const focused=document.activeElement===rail,scope=wrap.closest('#moodGrid')?'#moodGrid':'#dailyReflectionMood';onPick(+rail.value);if(focused)document.querySelector(scope+' .kona-slim-scale[data-dimension="'+dimension+'"] input')?.focus({preventScroll:true})};rail.onclick=()=>{if(!moved)onPick(value===+rail.value?null:+rail.value)};wrap.append(rail);
