 const ends=document.createElement('div');ends.className='kona-scale-ends';ends.innerHTML=dimension==='energy'?KonaI18n.markup("<span>Less energy</span><span>More energy</span>"):KonaI18n.markup("<span>Less pleasant</span><span>More pleasant</span>");wrap.append(ends);return wrap
