  const toggle=$('togglePrayerAdd');toggle.setAttribute('aria-expanded','false');toggle.onclick=()=>{form.hidden=!form.hidden;toggle.setAttribute('aria-expanded',String(!form.hidden));if(!form.hidden)form.querySelector('input').focus()};
  form.onsubmit=e=>{e.preventDefault();const v=form.querySelector('input').value.trim();if(!v)return;if(guardedMutation(()=>{db.prayers.push({id:uid(),title:v,note:'',since:nowLocal(),answered:null,lastPrayed:null,count:0})},KonaI18n.t("Prayer request was not saved."))){render();toast(KonaI18n.t("Added"))}};
  root.append(form);
