function influenceData(){
  const samples=[],all=[];
  for(const d of Object.keys(db.days)){
    const v=db.days[d];let es=null;
    for(const p of PHASES){
      const c=v.checkins?.[p],m=moodOf(c);if(!m)continue;all.push(m);
      const t=checkTime(c,p);if(t===null)continue;es??=dayEvents(d).filter(e=>INFLUENCE_CATS.includes(e.category));
      let best=null;for(const e of es){const z=mins(e.end);if(z<=t&&t-z<=180&&(!best||z>mins(best.end)))best=e}
      if(best)samples.push({cat:best.category,title:best.title,e:m.e,v:m.v});
    }
  }
  return{samples,all};
}
