  if(titles.length){const det=el('details','more',KonaI18n.markup("<summary>By event</summary>"));titles.sort((a,b)=>byTitle[b].length-byTitle[a].length).forEach(t=>det.append(row(escapeHTML(t),byTitle[t],3)));root.append(det)}
  root.append(el('p','micro',KonaI18n.format("Compared with the overall average: Mood ⟪0⟫ · Energy ⟪1⟫",[avgV.toFixed(1),avgE.toFixed(1)],false)));
