function allMemoEntries(){
 const entries=[];
 for(const [d,v] of Object.entries(db.days)){
  for(const session of v.sessions||[])if(session.kind==='devotion'||session.personalPrayer||(session.note||'').trim())entries.push({d,kind:session.personalPrayer?'personal':session.kind==='devotion'?'devotion':'event',title:session.personalPrayer?KonaI18n.t("Personal prayer"):KIND[session.kind]?.name||KonaI18n.t("Focus"),text:session.note||'',open:()=>openSessionNote(d,session)});
  const ids=new Set([...Object.keys(v.eventNoteTitles||{}),...Object.keys(v.eventNotes||{}),...Object.values(v.timeNotes||{}).flatMap(slot=>Object.keys(slot).filter(id=>id!=='free'))]);
  for(const id of ids){if(Object.values(db.settings.morningLectureAliases||{}).some(a=>a.includes(id)))continue;if(id==='__day_wrap'&&v.checkins?.night)continue;const text=eventMemoText(d,id);if(!text.trim()&&!eventNoteTitle(d,id))continue;const found=dayEvents(d).find(e=>e.id===id)||db.events.find(e=>e.id===id),wrap=id==='__day_wrap';const e=found||{id,title:wrap?KonaI18n.t("하루 마무리"):'이전 일정',start:wrap?'21:00':'06:30',end:wrap?'22:00':'08:00',category:'personal'};entries.push({d,kind:wrap?'wrap':'event',title:eventNoteTitle(d,id)||e.title,text,open:()=>{closeSheet('journalModal');changeDate(d);openRecordEditor(e)}})}
  for(const [hr,slots] of Object.entries(v.timeNotes||{})){const free=typeof slots?.free==='string'?slots.free:slots?.free?.text||'';if(!free.trim())continue;entries.push({d,kind:'event',title:KonaI18n.format("⟪0⟫:00 Free note",[String(hr).padStart(2,'0')],false),text:free,open:()=>{closeSheet('journalModal');changeDate(d);const h=Number(hr);openTimeNotes(h,dayEvents(d).filter(e=>mins(e.start)<(h+1)*60&&mins(e.end)>h*60),[])}})}
  for(const [id,text] of Object.entries(v.meals||{})){if(!String(text||'').trim())continue;const e=dayEvents(d).find(x=>x.id===id)||db.events.find(x=>x.id===id);entries.push({d,kind:'meal',title:e?.title||KonaI18n.t("Meal"),text:String(text),open:()=>{closeSheet('journalModal');changeDate(d);nav('today')}})}
  const noon=v.checkins?.noon;
  if(noon&&(noon.lectureQuote||noon.lectureReflection)){const text=[noon.lectureQuote?KonaI18n.format("Memorable words\n⟪0⟫",[noon.lectureQuote],false):'',noon.lectureReflection?KonaI18n.format("Reflection\n⟪0⟫",[noon.lectureReflection],false):''].filter(Boolean).join('\n\n');entries.push({d,kind:'class',title:KonaI18n.t("Morning class notes"),text,open:()=>{closeSheet('journalModal');changeDate(d);nav('checkin',{phase:'noon'})}})}
  for(const p of PHASES){const c=v.checkins?.[p],text=c?.note||'';if(!text)continue;entries.push({d,kind:p==='night'?'wrap':'check',title:PNAME[p],text,open:()=>{closeSheet('journalModal');changeDate(d);nav('checkin',{phase:p})}})}
 }
 return entries.sort((a,b)=>b.d.localeCompare(a.d));
}
