function renderSessionActions(){
 let root=$('sessionActions');if(!root){root=el('div');root.id='sessionActions';$('sessionMemo').after(root)}root.replaceChildren();if(!activeSessionNote)return;
 const {d,s}=activeSessionNote;if(!s.id){s.id=uid();save()}
 db.tasks.filter(t=>t.sourceSession?.date===d&&t.sourceSession.id===s.id).forEach(t=>root.append(btn('mini-btn','▶ '+escapeHTML(t.title),KonaI18n.t("Focus on linked task"),()=>{closeSheet('sessionNoteModal');nav('focus',{kind:'focus',taskKey:taskKey(t,nowLocal())})})));
 root.append(btn('mini-btn',KonaI18n.t("View record date ↗"),KonaI18n.t("Go to record date"),()=>{closeSheet('sessionNoteModal');changeDate(d);nav('today')}));
 root.append(btn('outline danger',KonaI18n.t("Delete session"),KonaI18n.t("Remove this focus, devotion, or prayer record"),()=>deleteReviewRecord({label:'session',remove:()=>removeSessionRecord(d,s)})));
}
