/* PHASE 3: keyboard support and one authoritative accessibility state sync. */
(()=>{
 const overlays=[...document.querySelectorAll('.modal-under')];
 const tabbable='button:not([disabled]),input:not([disabled]):not([type="hidden"]),select:not([disabled]),textarea:not([disabled]),a[href],[tabindex]:not([tabindex="-1"])';
 let lastTrigger=null;
 function topModal(){return document.querySelector('dialog[open]')?null:konaVisibleSheets().at(-1)||null}
 function syncNavigation(){
   document.querySelectorAll('.tabs button').forEach(b=>{
     if(b.classList.contains('active'))b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');
   });
   document.querySelectorAll('.phases button,#kindSeg button,#focusDurations button[data-time]').forEach(b=>b.setAttribute('aria-pressed',b.classList.contains('active')?'true':'false'));
 }
 function focusOnOpen(el){
   if(el.contains(document.activeElement))return;
   const first=el.querySelector('.sheet .top .close')||el.querySelector(tabbable);
   if(first)first.focus({preventScroll:true});
 }
 const obs=new MutationObserver(mutations=>{
   for(const m of mutations){
     if(m.attributeName==='hidden'&&m.target.matches('.modal-under')){
       const el=m.target;
       if(!el.hidden){
         lastTrigger=document.activeElement;
         focusOnOpen(el);
       }else if(!topModal()&&lastTrigger?.isConnected&&!lastTrigger.closest('[hidden]')){
         const former=lastTrigger;lastTrigger=null;
         former.focus({preventScroll:true});
       }
     }
   }
   syncNavigation();
 });
 overlays.forEach(el=>{
   if(!el.hasAttribute('role'))el.setAttribute('role','presentation');
   const dialog=el.querySelector('.sheet');
   if(dialog){dialog.setAttribute('role','dialog');dialog.setAttribute('aria-modal','true')}
   obs.observe(el,{attributes:true,attributeFilter:['hidden']});
 });
 document.querySelectorAll('.tabs button,.phases button,#kindSeg button,#focusDurations button[data-time]')
 .forEach(el=>obs.observe(el,{attributes:true,attributeFilter:['class']}));
 document.addEventListener('keydown',e=>{
   if(e.key!=="Tab")return;
   const modal=topModal();if(!modal)return;
   const items=[...modal.querySelectorAll(tabbable),...(tutorialPractice?$('guidedTour').querySelectorAll(tabbable):[])].filter(el=>el.getClientRects().length>0&&getComputedStyle(el).visibility!=='hidden');
   if(!items.length){e.preventDefault();return}
   const first=items[0],last=items.at(-1),active=document.activeElement;
   if(e.shiftKey&&(active===first||(!modal.contains(active)&&!$('guidedTour').contains(active)))){e.preventDefault();last.focus()}
   else if(!e.shiftKey&&(active===last||(!modal.contains(active)&&!$('guidedTour').contains(active)))){e.preventDefault();first.focus()}
 },true);
 syncNavigation();
})();

