function hasRecord(v){return !!(v?.headline?.trim()||v?.quickCaptureEntries?.length||v?.sessions?.some(s=>s.seconds>0)||Object.values(v?.eventNotes||{}).some(x=>typeof x==='string'&&x.trim())||Object.values(v?.reflectionNotes||{}).some(x=>typeof x==='string'&&x.trim())||Object.values(v?.checkins||{}).some(c=>c.note?.trim()||c.mood||c.lectureQuote?.trim()||c.classContext?.trim()||c.lectureReflection?.trim()))}
