;/* controller 16/16: 16-whole-app-accessibility.js */
/* Small, non-destructive UI enhancements layered after the existing controllers.
 * Avoids storing new keys or replacing any existing click handlers. */
(function(){
  const get=id=>document.getElementById(id);
  function decorate(){
    const textById={addEventBtn:KonaI18n.t("＋ Add event"),addTaskBtn:KonaI18n.t("＋ Add task")};
    for(const [id,label] of Object.entries(textById)){
      const el=get(id); if(!el)continue;
      el.textContent=label;el.setAttribute('aria-label',KonaI18n.t(id==='addEventBtn'?'Add event':'Add task',true));
      el.classList.add('kona-add-action');
    }
    for(const [id,label] of Object.entries({
      quickAddTask:KonaI18n.t("Add task"),quickAddEvent:KonaI18n.t("Add event"),calPrev:KonaI18n.t("Previous month"),calNext:KonaI18n.t("Next month"),
      weekPrev:KonaI18n.t("Previous week"),weekNext:KonaI18n.t("Next week"),focusMore:KonaI18n.t("More focus options"),
      backupNow:KonaI18n.t("Download JSON backup"),restoreNow:KonaI18n.t("Restore JSON backup"),
      focusNoteToggle:KonaI18n.t("Toggle session note")
    })){
      const el=get(id);if(el&&!el.getAttribute('aria-label'))el.setAttribute('aria-label',label);
    }
    const settingsPanel=document.querySelector('#kx-settings .settings-panel-body');
    if(settingsPanel&&!document.getElementById('konaSettingsHeading')){
      const h=document.createElement('h2');h.id='konaSettingsHeading';h.className='kona-settings-heading';h.textContent=KonaI18n.t("Settings");
      settingsPanel.prepend(h);
    }
    for(const el of document.querySelectorAll('#page-schedule .subtabs button,#page-focus #kindSeg button')){
      el.setAttribute('type','button');
    }
  }
  decorate();
})();

