;/* Compact writing fields and resilient decorative images. */
(function(){
 function fit(field){field.style.setProperty('height','auto','important');field.style.setProperty('height',Math.min(240,Math.max(field.id==='qc-text'?64:88,field.scrollHeight))+'px','important')}
 document.addEventListener('input',event=>{const field=event.target;if(field instanceof HTMLTextAreaElement&&(field.id==='qc-text'||field.matches('.rv-journal-main textarea')))fit(field)});
 document.addEventListener('error',event=>{const img=event.target;if(img instanceof HTMLImageElement&&img.src.includes('hibiscus-task-')){const fallback=document.createElement('span');fallback.className='flower-fallback';fallback.textContent=img.src.includes('-off.')?'❀':'🌺';fallback.setAttribute('role','img');fallback.setAttribute('aria-label',img.alt||KonaI18n.t("Flower",true));img.replaceWith(fallback)}},true);
})();

